// studies-data.js — 81 studies extracted from Neurevo bundle
const STUDIES = [
  {id:"cct-1",category:"cognitive-control-training",sampleSize:"12 studies (Total N = 1,317)",controlGroup:"Various (active, passive, waitlist, and sham controls across studies)",description:"'This systematic review found that cognitive control training is promising for reducing anxiety and depression in youth, specifically when the training results in 'cognitive transfer' (improvements in the trained task). The most consistent benefits were seen when using adaptive tasks targeted at inhibition or working memory in school settings, though commercial brain training packages showed mixed results.'",link:"https://doi.org/10.1016/j.jad.2021.12.108",doi:"10.1016/j.jad.2021.12.108"},
  {id:"cct-2",category:"cognitive-control-training",sampleSize:"52",controlGroup:"Waitlist control",description:"Participants with high emotion-related impulsivity completed a cognitive control training program (combined working memory and inhibition tasks) and saw significant reductions in impulsivity, decreases in brooding rumination, and increases in reappraisal. The waitlist control group showed no improvements.",link:"https://doi.org/10.1016/j.brat.2018.03.009",doi:"10.1016/j.brat.2018.03.009"},
  {id:"cct-3",category:"cognitive-control-training",sampleSize:"22",controlGroup:"passive",description:"Participants who completed a 15-minute cognitive control training session showed significantly higher reading comprehension and lower levels of distraction when faced with digital notifications compared to those who received no training.",link:"https://doi.org/10.1145/3675094.3677591",doi:"10.1145/3675094.3677591"},
  {id:"cct-4",category:"cognitive-control-training",sampleSize:"83",controlGroup:"active",description:"Those who did cognitive control training saw <strong>improved working memory and a reduction in rumination when experiencing low positive affect</strong>. The training did not increase the use or efficacy of adaptive strategies like positive reappraisal.",link:"https://doi.org/10.1037/emo0000169",doi:"10.1037/emo0000169"},
  {id:"cct-5",category:"cognitive-control-training",sampleSize:"92",controlGroup:"active",description:"Remitted depressed patients who did cognitive control training saw a <strong>significant reduction in the recurrence of depression</strong> one year later compared to the active control group.",link:"https://doi.org/10.1177/2167702620979775",doi:"10.1177/2167702620979775"},
  {id:"cct-6",category:"cognitive-control-training",sampleSize:"382",controlGroup:"None (single-arm trial)",description:"Participants completed a gamified web-based cognitive control training, and results showed that those with a <strong>moderate or high risk for internalizing disorders experienced the greatest reductions in anxiety and stress</strong> compared to low-risk individuals.",link:"https://doi.org/10.1016/j.invent.2022.100507",doi:"10.1016/j.invent.2022.100507"},
  {id:"cct-7",category:"cognitive-control-training",sampleSize:"382",controlGroup:"None (single-arm trial)",description:"Participants completed a gamified web-based cognitive control training, and while <strong>all groups saw improvements in repetitive negative thinking and cognitive performance</strong>, those with a <strong>moderate or high risk</strong> for internalizing disorders experienced the <strong>greatest reductions in anxiety and stress</strong>.",link:"https://doi.org/10.1016/j.invent.2022.100507",doi:"10.1016/j.invent.2022.100507"},
  {id:"cct-8",category:"cognitive-control-training",sampleSize:"147",controlGroup:"active (speed-of-response training)",description:"Healthy participants completed a gamified cognitive control training, and those in the highly gamified group reported significantly <strong>lower anxiety levels</strong> after training compared to the active control and low-gamification groups. No other emotional transfer effects were observed.",link:"https://doi.org/10.1007/s41465-019-00135-6",doi:"10.1007/s41465-019-00135-6"},
  {id:"cct-9",category:"cognitive-control-training",sampleSize:"47",controlGroup:"active (adaptive Visual Search task)",description:"Undergraduate students with high trait rumination who completed cognitive control training demonstrated reduced stress reactivity in the lab and a significant decrease in brooding during a subsequent naturalistic stressor (exams). The active control group did not show these improvements in resilience or brooding.",link:"https://doi.org/10.1016/j.brat.2015.03.010",doi:"10.1016/j.brat.2015.03.010"},
  {id:"cct-10",category:"cognitive-control-training",sampleSize:"216",controlGroup:"zero training sessions (no training)",description:"A minimum of 10 cognitive control training sessions was required to see a significant short-term decrease in depressive symptoms and a sustained long-term reduction in perseverative thinking. Participants who completed fewer than 10 sessions did not show these benefits.",link:"https://doi.org/10.1037/ccp0000945",doi:"10.1037/ccp0000945"},
  {id:"rrt-1",category:"relational-reasoning-training",sampleSize:"26",controlGroup:"passive",description:"Irish secondary school students (n=26) with an average age of 16.5 years were divided into an experimental group and a control group. The experimental group underwent SMART relational skills training for a 12-week period involving bi-weekly 45-minute sessions, while the control group continued with regular classroom activities. The training group achieved a mean increase of approximately 18.8 points in Full Scale IQ (FSIQ) on the WASi, a rise of more than one standard deviation. They also saw significant increases in Verbal IQ (approx. 20 points) and Performance IQ (approx. 13.5 points), significantly improving scores on Vocabulary, Block Design, Similarities, and Matrix Reasoning subtests. The participants who did not train saw no significant increases in any of these metrics.",link:"https://link.springer.com/article/10.1007/s10864-018-9302-2",doi:"10.1007/s10864-018-9302-2"},
  {id:"rrt-2",category:"relational-reasoning-training",sampleSize:"49",controlGroup:"Active (chess)",description:"Irish primary school students (mean age 8.67) engaged in SMART relational training or an active chess control condition over a four-month period. The training group achieved a significant Non-Verbal IQ increase of 8.9 points (effect size 0.99), while the chess group showed no significant gains. Post-training NVIQ predicted variance in reading comprehension scores over and above baseline ability, although no transfer to mathematics outcomes was observed.",link:"https://doi.org/10.1007/s41465-020-00187-z",doi:"10.1007/s41465-020-00187-z"},
  {id:"rrt-3",category:"relational-reasoning-training",sampleSize:"45 (15 in Experiment 1; 30 in Experiment 2)",controlGroup:"None (pre-test/post-test design)",description:"Two experiments evaluated the effects of SMART relational training on intelligence and scholastic aptitude. In Experiment 1, children aged 11-12 (n=15) completed the training and achieved a significant mean Full Scale IQ rise of 23 points (from 97 to 120) on the WISC-IV. In Experiment 2, students aged 15-17 (n=30) completed the training and demonstrated significant increases in Differential Aptitude Test scores for Verbal Reasoning, Numerical Reasoning, and overall Educational Aptitude.",link:"https://doi.org/10.1016/j.lindif.2016.03.001",doi:"10.1016/j.lindif.2016.03.001"},
  {id:"rrt-4",category:"relational-reasoning-training",sampleSize:"21",controlGroup:"Passive",description:"Swedish high school students (mean age 17.3) were assigned to SMART relational training or a no-training control condition for 8â€“10 weeks. The training group demonstrated significant improvements in general intelligence (Raven's Standard Progressive Matrices) and relational skills (RAI). However, the intervention did not result in significant gains in mathematical performance compared to the control group, and training adherence was notably low.",link:"https://www.ijpsy.com/volumen16/num2/439/relational-frame-theory-mathematical-and-EN.pdf",doi:""},
  {id:"rrt-5",category:"relational-reasoning-training",sampleSize:"35",controlGroup:"None (dosage analysis)",description:"Socially disadvantaged, non-English speaking children in Bangladesh (ages 6â€“14) engaged in SMART relational training over a three-month period. Analyses focused on training 'dosage,' revealing that the specific number of training stages completed significantly predicted gains in fluid intelligence (Raven's Standard Progressive Matrices). Participants who progressed beyond the introductory stages achieved significantly higher scores than those with lower engagement, demonstrating the intervention's efficacy in austere settings.",link:"https://doi.org/10.1007/s40732-018-0273-4",doi:"10.1007/s40732-018-0273-4"},
  {id:"rrt-6",category:"relational-reasoning-training",sampleSize:"59",controlGroup:"Matched waiting control",description:"High school students (10th and 11th grade) in the USA completed SMART relational training or continued with standard instruction over a 10-week period. The training group demonstrated significant and large gains in standardized Classroom Diagnostic Tools (CDT) scores for Mathematics (d=1.19) and Reading (d=1.11) compared to the control group, even when controlling for baseline scores. While the control group showed modest improvements attributed to regular schooling, the intervention group achieved significantly higher growth with 100% protocol adherence.",link:"https://doi.org/10.1007/s10864-024-09559-3",doi:"10.1007/s10864-024-09559-3"},
  {id:"rrt-7",category:"relational-reasoning-training",sampleSize:"45 (15 in Experiment 1; 30 in Experiment 2)",controlGroup:"None (pre-test/post-test design)",description:"Two experiments evaluated the effects of SMART relational training on intelligence and scholastic aptitude. In Experiment 1, children aged 11â€“12 (n=15) completed the training and achieved a significant mean Full Scale IQ rise of 23 points (from 97 to 120) on the WISC-IV, with a large effect size of 2.33. In Experiment 2, students aged 15â€“17 (n=30) completed the training and demonstrated significant increases in Differential Aptitude Test (DAT) scores, specifically with Verbal Reasoning rising from 63.2 to 69.5, Numerical Reasoning from 54.5 to 67.6, and overall Educational Aptitude from 58.9 to 68.",link:"https://doi.org/10.1016/j.lindif.2016.03.001",doi:"10.1016/j.lindif.2016.03.001"},
  {id:"rrt-8",category:"relational-reasoning-training",sampleSize:"125",controlGroup:"Active (Scratch computer coding)",description:"Adolescent school pupils (mean age 13.4) were assigned to SMART relational training or an active Scratch computer coding control condition for 3 months. The SMART training group achieved a significant Non-Verbal IQ increase of 5.98 points, while the active control group showed no significant gains. However, both groups demonstrated similar improvements in processing speed over time, suggesting no differential effect of relational training on simple psychomotor speed compared to coding.",link:"https://doi.org/10.1007/s10864-020-09399-x",doi:"10.1007/s10864-020-09399-x"},
  {id:"wmt-1",category:"working-memory-training",sampleSize:"148 (50 N-back, 50 Method of Loci, 48 Control)",controlGroup:"Passive (blank control)",description:"Young adults completed 20 days of dual n-back or method of loci training. The dual n-back group significantly improved verbal and visual working memory capacity on the trained task. While both interventions enhanced performance on an untrained verbal digit-span task, only dual n-back training transferred to a visual change detection task, demonstrating superior transfer effects.",link:"https://doi.org/10.1038/s41598-021-82663-w",doi:"10.1038/s41598-021-82663-w"},
  {id:"wmt-2",category:"working-memory-training",sampleSize:"55",controlGroup:"Passive (no training)",description:"Healthy young adults engaged in an adaptive spatial working memory training task (monitoring scene identities and locations, 3D N-Back) for 20 days. The training group demonstrated significant improvements in fluid intelligence compared to the passive control group. Additionally, participants who achieved high performance gains on the training task showed significant transfer effects to episodic memory, specifically improving object and scene recognition, recollection, and familiarity.",link:"https://doi.org/10.1371/journal.pone.0050431",doi:"10.1371/journal.pone.0050431"},
  {id:"wmt-3",category:"working-memory-training",sampleSize:"50",controlGroup:"Active (conventional teaching)",description:"Iranian EFL learners (university students aged 25â€“40) participated in a vocabulary learning course where the experimental group engaged in dual n-back working memory training alongside standard instruction. The dual n-back group demonstrated significantly higher scores in both immediate vocabulary recall and delayed retention tests compared to the control group, supporting the efficacy of working memory training for second language vocabulary acquisition.",link:"https://doi.org/10.18844/gjflt.v13i1.6486",doi:"10.18844/gjflt.v13i1.6486"},
  {id:"wmt-4",category:"working-memory-training",sampleSize:"40",controlGroup:"Active (non-adaptive dual 1-back)",description:"Chinese adolescents (ages 11â€“17) completed 10 days of adaptive dual n-back working memory training or a non-adaptive control task. The adaptive training group reported a significant reduction in test anxiety symptoms compared to the control group. However, the intervention failed to produce significant differential improvements in attentional control across self-report and behavioral measures.",link:"https://doi.org/10.1186/s40359-024-01597-w",doi:"10.1186/s40359-024-01597-w"},
  {id:"wmt-5",category:"working-memory-training",sampleSize:"60 (35 patients, 25 healthy controls)",controlGroup:"Active (Treatment as Usual)",description:"Inpatients with methamphetamine use disorder (MUD) completed 4 weeks of smartphone-based working memory training (dual n-back) alongside standard treatment or standard treatment alone. The training group demonstrated a 35% learning rate and reported significantly higher improvements in mood, feelings of self-control, and self-regulation compared to the control group at follow-up. Additionally, the training group showed significant reductions in total impulsivity and planning deficits relative to their baseline.",link:"https://doi.org/10.1007/s00213-017-4597-6",doi:"10.1007/s00213-017-4597-6"},
  {id:"wmt-6",category:"working-memory-training",sampleSize:"42 (22 training, 20 control)",controlGroup:"Active (animal memory task)",description:"Healthy adult participants (mean age ~21.8) completed 20 days of Running Working Memory training or an active control memory task. The training group showed a significant increase in resting high-frequency heart rate variability (HF-HRV), an objective physiological marker of general emotion regulation, compared to the control group. These gains were maintained at a 3-month follow-up, and improvements in working memory performance were positively correlated with gains in HF-HRV.",link:"https://doi.org/10.1080/09602011.2025.2487430",doi:"10.1080/09602011.2025.2487430"},
  {id:"wmt-7",category:"working-memory-training",sampleSize:"177",controlGroup:"Active (sham training)",description:"Low-income adults (ages 40â€“60) who smoke were randomized to 15 sessions of computerized working memory training or a sham control task. Working memory training significantly reduced cigarette smoking, but specifically among participants with high baseline delay discounting (a preference for immediate over delayed rewards). Conversely, participants with high delay discounting in the control group increased their smoking, suggesting the intervention is particularly effective for individuals with elevated impulsivity.",link:"https://doi.org/10.1093/ntr/ntac005",doi:"10.1093/ntr/ntac005"},
  {id:"wmt-8",category:"working-memory-training",sampleSize:"100 (55 younger, 45 older)",controlGroup:"Active (low-level practice)",description:"Younger (20â€“30) and older (60â€“70) adults completed 5 weeks of adaptive working memory training or a low-intensity active control task. The adaptive training group demonstrated significant improvements in working memory and transfer to sustained attention and self-reported cognitive functioning, though no transfer to fluid intelligence or inhibition was observed compared to active controls. These gains and transfer effects were maintained at a 3-month follow-up for both age groups.",link:"https://doi.org/10.3389/fnhum.2012.00063",doi:"10.3389/fnhum.2012.00063"},
  {id:"wmt-9",category:"working-memory-training",sampleSize:"17,648",controlGroup:"Active (Rotation training used as comparison)",description:"In a large-scale study, children aged 6â€“8 completed a 7-week app-based intervention combining mathematical practice with randomly assigned spatial cognitive training: visuospatial working memory (VSWM), non-verbal reasoning (NVR), or spatial rotation. Results indicated that training VSWM and NVR led to significantly greater improvements in mathematical learning compared to rotation training. The findings suggest that the ability to maintain spatial information (VSWM) and perform spatial reasoning is more critical for mathematical transfer than spatial manipulation (rotation).",link:"https://doi.org/10.1038/s41562-021-01118-4",doi:"10.1038/s41562-021-01118-4"},
  {id:"wmt-10",category:"working-memory-training",sampleSize:"106 (33 non-medicated ADHD, 42 medicated ADHD, 45 controls)",controlGroup:"Active (fixed dual 1-back training)",description:"'Young adults (ages 18â€“30) with ADHD and neurotypical controls completed at least 18 daily sessions of computerized dual N-back (DNB) training over one month. Participants were assigned to either an adaptive conditionâ€”where the 'N' level increased based on performanceâ€”or a fixed-difficulty control condition. The adaptive group showed significantly greater gains in task performance and a notable 'near transfer' improvement in verbal working memory, specifically on the Digit Span Backward subtest of the WAIS-IV. However, the training yielded very limited or non-significant benefits for visuospatial memory (measured by the Corsi task), suggesting that improvements were largely specific to the trained modality. Notably, the use of stimulant medication did not significantly alter the magnitude of the cognitive gains achieved through training.'",link:"https://doi.org/10.3390/brainsci15090998",doi:"10.3390/brainsci15090998"},
  {id:"wmt-11",category:"working-memory-training",sampleSize:"33 children (ages 9â€“11)",controlGroup:"Active control (played irrelevant computer games)",description:"Researchers investigated whether training the <strong>updating</strong> component of working memoryâ€”the ability to monitor and replace old information with new, relevant dataâ€”could directly improve fluid intelligence in children. Using a double-blind design, the training group completed 15 sessions of a running memory task (recalling the last few items in a sequence of animals or locations) over four weeks. Unlike tasks that rely on memory storage, this task focused purely on the 'central executive' function of the brain. Following the intervention, the training group showed a significant increase in fluid intelligence scores on Raven's Standard Progressive Matrices compared to the control group. These results suggest that strengthening the brain's ability to control attention and update information in the prefrontal cortex can lead to broad improvements in general reasoning and problem-solving skills.,descriptionKey:'studies.entries.wmt11.description",link:"https://doi.org/10.1007/s11434-011-4553-5",doi:"10.1007/s11434-011-4553-5"},
  {id:"wmt-12",category:"working-memory-training",sampleSize:"",controlGroup:"N/A (No active training control; used high-capacity group as baseline comparison)",description:"Researchers investigated whether training the brain's 'gatekeeper' functionâ€”<strong>filtering efficiency</strong>â€”could expand visual working memory capacity in college students. Participants were split into high- and low-capacity groups; the low-capacity group then completed 20 days of adaptive training tasks that required focusing on target items (such as specific colors or shapes) while ignoring distractors. After training, the low-capacity group showed significant improvements in a change-detection task, with their neural activity (Contralateral Delay Activity) becoming similar to that of high-capacity individuals. These benefits were maintained at a three-month follow-up and transferred to an untrained verbal working memory task. However, the training did not improve fluid intelligence (Raven's Matrices), suggesting that while filtering efficiency can be trained to boost memory capacity, this does not necessarily translate to broader reasoning abilities.,descriptionKey:'studies.entries.wmt12.description",link:"https://doi.org/10.3389/fpsyg.2017.00196",doi:"10.3389/fpsyg.2017.00196"},
  {id:"wmt-13",category:"working-memory-training",sampleSize:"130 healthy adults (aged 18â€“55)",controlGroup:"Active (simple listening task) and No-training control",description:"Researchers compared the effectiveness of two different cognitive training methodsâ€”a dual n-back task (simultaneous visual and auditory processing) and a dichotic listening (DL) task (processing different auditory stimuli in each ear)â€”against active and passive controls. Participants completed twenty 15-minute sessions over four weeks. Both training groups showed improvements in episodic memory and a positive trend in an untrained working memory span task compared to the no-training group. However, the dichotic listening training uniquely enhanced choice reaction performance, suggesting that training focused on processing competing auditory information may have specific benefits for rapid decision-making and selective attention.',descriptionKey:'studies.entries.wmt13.description",link:"https://doi.org/10.1007/s41465-020-00202-3",doi:"10.1007/s41465-020-00202-3"},
  {id:"wmt-14",category:"working-memory-training",sampleSize:"30 healthy students (15 traditional n-back, 15 executive n-back)",controlGroup:"Active (traditional n-back training)",description:"Researchers tested whether adding a manipulation component to classic n-back (executive n-back) would produce broader transfer than traditional n-back. In the executive task, participants compared the current weekday to the n-back weekday plus one day, requiring ongoing mental transformation rather than simple repetition matching. After six daily sessions, the executive group showed significantly greater intermediate transfer to Operation Span (a structurally different working memory paradigm) and greater far transfer to task switching (cognitive flexibility). These gains remained evident at a 3-month follow-up. Neither group showed a significant advantage for fluid intelligence or inhibitory control, suggesting that benefits were strongest for domains with closer executive-process overlap.",link:"https://doi.org/10.3758/s13423-025-02773-8",doi:"10.3758/s13423-025-02773-8"},
  {id:"wmt-15",category:"working-memory-training",sampleSize:"76 healthy participants",controlGroup:"Active (simple memory task matched for duration and engagement without adaptive difficulty)",description:"Healthy young adults completed 40 sessions of an adaptive running memory task over eight weeks to investigate how working memory training (WMT) reorganizes brain networks. The training group showed significant cognitive improvements, notably reducing reaction times in both near-transfer tasks (updating and switching functions) and far-transfer tasks (phonological loop processing). These behavioral gains were linked to a reduction in the participation coefficient (PC) within the sensorimotor network, suggesting that the brain became more efficient by reducing redundant cross-network interactions. Furthermore, node-specific changes were observed in executive control and attention hubs, such as the left prefrontal cortex and the temporo-occipital-parietal junction. Most notably, the researchers found that these changes in network integration were significantly correlated with the density of dopamine D2, mu-opioid, and glutamate (mGluR5) receptors, providing evidence for the neurochemical systems that underpin cognitive plasticity.",link:"https://doi.org/10.1093/cercor/bhaf081",doi:"10.1093/cercor/bhaf081"},
  {id:"wmt-16",category:"working-memory-training",sampleSize:"40 university students",controlGroup:"Active (completed a simple visual search task)",description:"'Researchers investigated whether 15 days of dual n-back training could improve how individuals recover from mistakes, a phenomenon known as post-error performance. While the control group performed a simple visual search task, the training group practiced dividing their attention between auditory and visual stimuli. Results showed that working memory training successfully eliminated post-error slowing (PES)â€”the typical delay in response time following an errorâ€”without decreasing accuracy. This suggests that the 'splitting skill' developed during n-back training, which involves managing old information while processing new inputs, effectively transfers to the cognitive adjustments required after making an error. However, the training did not affect the flanker effect, indicating that it boosted specific coordination skills rather than fundamental inhibitory control.'",link:"https://doi.org/10.3389/fpsyg.2020.00370",doi:"10.3389/fpsyg.2020.00370"},
  {id:"wmt-17",category:"working-memory-training",sampleSize:"42 undergraduates (20 trained; 22 control)",controlGroup:"Passive (untrained)",description:"Undergraduates completed 20 sessions of training over four weeks using adaptive complex working memory (CWM) span tasks. Unlike simple memory tasks, these CWM tasks required participants to store information (letters or locations) while simultaneously performing secondary processing demands, such as lexical or symmetry decisions. After training, the experimental group showed significant improvements in temporary memory capacity and 'far transfer' to two disparate cognitive skills: cognitive control (Stroop task) and reading comprehension. Notably, the increase in spatial working memory span was a strong and significant predictor of the improvements in reading comprehension. However, the training did not lead to gains in fluid intelligence (Raven's APM) or general reasoning. These findings suggest that CWM training enhances a domain-general attentional mechanismâ€”the ability to coordinate information maintenance while facing concurrent distractionâ€”which can be used as a tool to promote important academic and cognitive skills.",link:"https://doi.org/10.3758/PBR.17.2.193",doi:"10.3758/PBR.17.2.193"},
  {id:"wmt-18",category:"working-memory-training",sampleSize:"65 total (23 children with learning difficulties in the training group; 22 children with learning difficulties and 20 children without in active control groups)",controlGroup:"Active (completed unadaptive versions of the training tasks at one-third the volume)",description:"'Middle school students with learning difficulties (LDs) participated in 28 days of intensive, computerized working memory (WM) updating training for approximately 40 minutes per day. The intervention used three adaptive versions of a running memory task (letters, animals, and locations) designed to train the 'central executive' ability to monitor and replace irrelevant information with new data. Following the training, the experimental group showed significant 'near transfer' improvements in WM accuracy (2-back task) and a notable 'far transfer' gain in mathematical ability. Neural assessments (ERPs) revealed that these behavioral gains were accompanied by increased brain activity, specifically larger amplitudes in the N160 and P300 components, which represent visual recognition and updating processing. These findings suggest that targeted WM updating training can mitigate the symptoms of LDs by enhancing core cognitive control and mathematical achievement.'",link:"https://doi.org/10.3389/fnhum.2018.00154",doi:"10.3389/fnhum.2018.00154"},
  {id:"cps-1",category:"creative-problem-solving",sampleSize:"296 total (149 experimental; 147 control)",controlGroup:"Active (standard schooling without specialized problem-solving training)",description:"'Adolescents (beginning at age 15) in Serbia participated in a longitudinal, three-year study to determine if intensive training in creative problem-solving could boost general intelligence. While the control group followed a standard high school curriculum, the experimental group received weekly exercises designed to require radical reorganization of problems and divergent thinking. At the end of the intervention and in follow-up testing at age 19, the experimental group demonstrated a significant 'far transfer' effect, gaining an average of 10 to 15 IQ points more than the control group across 28 different intelligence tests. These findings challenge the idea that intelligence is fixed, suggesting that prolonged and intensive cognitive training within a natural school environment can produce substantial, lasting gains in both fluid and crystallized intelligence.',descriptionKey:'studies.entries.cps1.description",link:"https://doi.org/10.3390/jintelligence8040041",doi:"10.3390/jintelligence8040041"},
  {id:"cps-2",category:"creative-problem-solving",sampleSize:"296 high school students (149 experimental; 147 control)",controlGroup:"Active (standard high school curriculum in Yugoslavia)",description:"'In this longitudinal study conducted in the mid-1970s, researchers investigated whether long-term training in creative problem-solving could increase general intelligence scores in adolescents. Students in the experimental group received specialized exercises three to four times per week over a three-year period, focusing on divergent thinking and the reorganization of complex problems. Assessment across 28 different measures of fluid and crystallized intelligence revealed significant improvements in the training group compared to the control group. These gains were found to persist even one year after the training had concluded, with the most pronounced effects observed in measures of fluid intelligence. The findings suggest that intelligence is malleable and that intensive, school-based cognitive interventions can lead to lasting 'far transfer' effects on general mental abilities.',descriptionKey:'studies.entries.cps2.description",link:"https://doi.org/10.1016/0160-2896(86)90016-4",doi:"10.1016/0160-2896(86)90016-4"},
  {id:"ic-1",category:"inhibitory-control",sampleSize:"194 total (30 in adolescent training group, 30 in adolescent active control, 47 in adult training group, 45 in adult active control, and 42 in a passive control group)",controlGroup:"Active (Stop Signal task without online feedback) and Passive (no training)",description:"'Adolescents (average age 15) and young adults (average age 20) completed nine sessions of computerized response inhibition training over three weeks using the Stop Signal paradigm. The experimental groups received immediate online feedback to help them balance response speed and accuracy. While both age groups improved on the trained task, the adolescent training group demonstrated significantly broader 'transfer' effects to other cognitive skills. Specifically, both training groups improved on a similar response inhibition task (Go/No-go), but only the adolescents showed significant gains in interference suppression (Stroop task) and high-load working memory (3-back task). No group showed improvements in fluid intelligence. These findings suggest that inhibition training with immediate feedback is more formative during adolescence, a period of high cognitive plasticity, than in adulthood.',descriptionKey:'studies.entries.ic1.description",link:"https://doi.org/10.3724/SP.J.1041.2020.001",doi:"10.3724/SP.J.1041.2020.001"},
  {id:"ic-2",category:"inhibitory-control",sampleSize:"64 total (17 updating, 16 inhibition, 13 task switching, 18 control)",controlGroup:"Routine (followed standard interpreting curriculum without executive function training)",description:"Student interpreters (undergraduate majors) completed 15 sessions of adaptive computerized training over five weeks, targeting one of the three core components of executive function (EF): updating, inhibition, or task switching (TS). While all training groups improved in their specific targeted cognitive skill, only the inhibition training group (which practiced ignoring distractors in Stroop and Flanker tasks) demonstrated statistically significant and durable gains in consecutive interpreting (CI) performance. These improvements were maintained three months after the training ended. Researchers conclude that inhibition is a critical mechanism for interpreters, as it allows them to suppress interference from the source language and rapidly access the correct translation equivalents. The study provides evidence that cognitive control training can effectively transfer to the complex linguistic task of interpreting.",link:"https://doi.org/10.3390/bs15111477",doi:"10.3390/bs15111477"},
  {id:"rft-1",category:"relational-frame-theory",sampleSize:"16",controlGroup:"Single-case design (Multiple baseline)",description:"Children aged 4-5 who initially failed to derive symmetrical relations (If A=B, then B=A) were successfully taught this skill using <strong>Multiple Exemplar Training (MET)</strong>. They subsequently generalized this ability to new stimuli without further training.",link:"",doi:""},
  {id:"rft-2",category:"relational-frame-theory",sampleSize:"20",controlGroup:"Single-case design (Baseline control)",description:"Replicated the previous findings and extended them to prove that naming (knowing the words for objects) was not required to learn symmetry. It confirmed that relational flexibility itself is a learnable operant behavior.",link:"",doi:""},
  {id:"rft-3",category:"relational-frame-theory",sampleSize:"9",controlGroup:"Within-subject design",description:"'Demonstrated the RFT model of <strong>Analogical Reasoning</strong>. Participants learned to match relations to relations (e.g., matching a 'Same' relation to another 'Same' relation) based on abstract physical properties, effectively modeling how humans solve analogies.'",link:"",doi:""},
  {id:"rft-4",category:"relational-frame-theory",sampleSize:"3",controlGroup:"Single-case design (Multiple baseline)",description:"'Young children who did not understand the concept of 'Opposite' were successfully taught the concept using MET with coins. Once trained, they could immediately apply 'Opposite' logic to brand new stimuli.'",link:"",doi:""},
  {id:"rft-5",category:"relational-frame-theory",sampleSize:"24",controlGroup:"No-training control",description:"'Successfully applied Multiple Exemplar Training to <strong>Comparative Relations</strong> (More/Less). Participants trained with multiple examples of 'more than' and 'less than' generalized this reasoning ability to arbitrary symbols.'",link:"https://doi.org/10.1901/jaba.2007.7-06",doi:"10.1901/jaba.2007.7-06"},
  {id:"rft-6",category:"relational-frame-theory",sampleSize:"27",controlGroup:"Randomized Control Trial (Treatment as Usual)",description:"Children with autism receiving the <strong>PEAK</strong> (RFT-based) curriculum showed statistically significant gains in derived language skills and cognitive performance compared to the control group receiving standard care.",link:"https://doi.org/10.1007/s10864-015-9219-y",doi:"10.1007/s10864-015-9219-y"},
  {id:"rft-7",category:"relational-frame-theory",sampleSize:"4",controlGroup:"Single-case design (Multiple probe)",description:"'Demonstrated that Multiple Exemplar Training facilitated the emergence of 'derived relations' in second-language learning, significantly speeding up vocabulary acquisition in preschool children.'",link:"",doi:""},
  {id:"rft-8",category:"relational-frame-theory",sampleSize:"22",controlGroup:"Within-subject design",description:"Participants successfully derived analogies between two completely separate networks of stimuli (Cross-domain analogy). This provided a functional-analytic model for complex, creative thinking.",link:"https://doi.org/10.1901/jeab.2011.95-369",doi:"10.1901/jeab.2011.95-369"},
  {id:"rft-9",category:"relational-frame-theory",sampleSize:"13 (7 typically developing, 6 ASD)",controlGroup:"Single-case design (Multiple baseline)",description:"Children with autism initially failed to demonstrate analogical reasoning. Using RFT-based Multiple Exemplar Training, all participants successfully acquired analogical responding and generalized it to novel stimuli.",link:"https://doi.org/10.1007/s40732-021-00493-8",doi:"10.1007/s40732-021-00493-8"},
  {id:"rft-10",category:"relational-frame-theory",sampleSize:"25",controlGroup:"Cross-sectional developmental / Training phase",description:"Demonstrated a developmental trajectory where older children could perform analogies and younger ones could not. Younger children who failed baseline were successfully _trained_ to perform analogies, accelerating this cognitive milestone.",link:"https://doi.org/10.1007/s40732-021-00468-9",doi:"10.1007/s40732-021-00468-9"},
  {id:"rft-11",category:"relational-frame-theory",sampleSize:"20 (12 adults, 8 children)",controlGroup:"Baseline control",description:"A landmark study showing a significant correlation between derived relational responding and Full Scale IQ. Crucially, training participants to derive relations resulted in statistically significant increases in their actual IQ scores.",link:"https://doi.org/10.1080/15021149.2010.11434333",doi:"10.1080/15021149.2010.11434333"},
  {id:"rft-12",category:"relational-frame-theory",sampleSize:"23",controlGroup:"Correlational analysis",description:"Found that scores on the PEAK assessment (RFT curriculum) correlated strongly with scores on standard IQ tests (WISC/WPPSI), suggesting that teaching the PEAK curriculum is effectively teaching the components of IQ.",link:"https://doi.org/10.1016/j.rasd.2014.05.005",doi:"10.1016/j.rasd.2014.05.005"},
  {id:"rft-13",category:"relational-frame-theory",sampleSize:"Theory Paper",controlGroup:"N/A",description:"'Synthesizes Behavior Analysis (RFT) and Cognitive Psychology (Relational Complexity Theory), arguing that Fluid Intelligence is functionally the ability to reason relationally. It proposes that 'processing capacity' is limited by the number of relations a person can manipulate simultaneously.'",link:"https://doi.org/10.1016/j.intell.2020.101491",doi:"10.1016/j.intell.2020.101491"},
  {id:"rft-14",category:"relational-frame-theory",sampleSize:"Theory Paper",controlGroup:"N/A",description:"'Establishes <strong>Relational Complexity Theory (RCT)</strong>. It defines intelligence by the number of variables (unary, binary, ternary, quaternary) a person can mentally manipulate at once, identifying this 'processing capacity' as the bottleneck of human cognition.'",link:"https://doi.org/10.1016/j.tics.2010.08.005",doi:"10.1016/j.tics.2010.08.005"},
  {id:"rft-15",category:"relational-frame-theory",sampleSize:"Clinical Sample (Alzheimer's)",controlGroup:"Active Control (Drug therapy alone)",description:"Patients receiving RFT training (as an add-on to drug therapy) showed <strong>slower cognitive decline</strong> and better retention of skills than those on drug therapy alone.",link:"",doi:""},
  {id:"rft-16",category:"relational-frame-theory",sampleSize:"30",controlGroup:"Baseline control",description:"Showed that even _brief_ variants of the training using strict <strong>Response Latency</strong> deadlines could produce measurable changes in speed of thinking and IQ sub-test performance.",link:"https://doi.org/10.1080/15021149.2018.1507087",doi:"10.1080/15021149.2018.1507087"},
  {id:"aposner-1",category:"aposner",sampleSize:"54",controlGroup:"Active (non-adaptive Posner task)",description:"University students completed 12 days of adaptive semantic long-term memory retrieval (LTMR) training or a non-adaptive active control task. The training group demonstrated significant improvements in semantic retrieval efficiency, evidenced both behaviorally and by reduced N400 ERP amplitudes (indicating more efficient automatic retrieval). Significant transfer effects were observed for reading fluency, working memory updating, and task switching, though no gains were found for fluid intelligence or interference control.",link:"https://doi.org/10.1016/j.biopsycho.2024.108789",doi:"10.1016/j.biopsycho.2024.108789"},
  {id:"warmup-1",category:"warm-ups",sampleSize:"63 (31 elite athletes; 32 older adults)",controlGroup:"Active (physical warmup) and passive (no warmup)",description:"Two studies examined the effects of combined physical and cognitive warmups on performance under rested and sleep-deprived conditions. In elite padel players (n=31), intermixing short-to-medium duration cognitive tasks (10â€“17.5 min) with physical warmups improved sport and cognitive performance, whereas long durations (30 min) impaired it. In sedentary older adults (n=32), combined warmups produced greater gains in strength, endurance, and cognition than physical-only or no-warmup conditions. In both groups, combined warmups effectively mitigated performance deficits caused by sleep deprivation.",link:"https://doi.org/10.3390/brainsci15030235",doi:"10.3390/brainsci15030235"},
  {id:"warmup-2",category:"warm-ups",sampleSize:"63 (28 in Experiment 1; 35 in Experiment 2)",controlGroup:"Within-subjects (control lectures without exercise)",description:"'College students in an Introductory Psychology course completed a 'cognitive calisthenics' intervention (complex cancellation tasks) immediately prior to specific lectures. Across two experiments, students performed significantly better on exam questions related to material covered in the cognitive exercise condition compared to the control condition. While self-reports indicated improved attentiveness following the exercises, no significant difference was observed on immediate post-lecture quizzes.'",link:"https://doi.org/10.1177/00986283221084907",doi:"10.1177/00986283221084907"},
  {id:"impulsivity-1",category:"impulsivity-mood-wm",sampleSize:"27",controlGroup:"Active (yoked control training)",description:"Stimulant users in treatment (n=27) were randomly assigned to working memory training or a yoked control training group. The working memory training group showed significantly reduced rates of delay discounting (valuing immediate rewards less excessively), whereas the control group showed no change. The training did not affect other cognitive measures, but the reduction in discounting was positively correlated with improvements in working memory performance, suggesting a functional link between working memory capacity and future-oriented decision-making.",link:"https://doi.org/10.1016/j.biopsych.2010.08.017",doi:"10.1016/j.biopsych.2010.08.017"},
  {id:"impulsivity-2",category:"impulsivity-mood-wm",sampleSize:"61 (41 in WMT group; 20 in Control group)",controlGroup:"Passive (non-intervention)",description:"Healthy young adults completed 4 weeks of computerized working memory training or served as non-intervention controls. The training group reported significant reductions in negative mood states, specifically anger-hostility, depression-dejection, and fatigue-inertia, compared to the control group. Functional MRI analysis revealed that the training group exhibited reduced brain activity in the left posterior insula and frontoparietal regions during tasks that evoked negative emotions, providing neural evidence for the observed improvements in emotional regulation.",link:"https://doi.org/10.3389/fnsys.2014.00200",doi:"10.3389/fnsys.2014.00200"},
  {id:"impulsivity-3",category:"impulsivity-mood-wm",sampleSize:"126",controlGroup:"Active (yoked non-adaptive placebo)",description:"Mid-life adults (ages 40â€“60) recruited from a medically underserved community completed 15 sessions of computerized working memory training or a matched active control intervention. The training group demonstrated significant improvements in working memory performance compared to the control group. While the intervention did not produce a direct main effect on delay discounting, structural equation modeling revealed that the training-induced improvements in working memory significantly mediated a reduction in delay discounting for larger rewards ($1,000).",link:"https://doi.org/10.1093/abm/kaz010",doi:"10.1093/abm/kaz010"},
  {id:"impulsivity-4",category:"impulsivity-mood-wm",sampleSize:"50",controlGroup:"Passive (Treatment as Usual)",description:"Male opioid addicts maintained on methadone therapy (n=50) were assigned to a 4-week mobile-based intervention combining working memory and attention control training or a treatment-as-usual control condition. The intervention group demonstrated significant reductions in craving and impulsivity compared to the control group. However, the training did not lead to significant improvements in working memory capacity as measured by the digit span test.",link:"http://dx.doi.org/10.32598/ijpcp.29.4.4643.1",doi:"10.32598/ijpcp.29.4.4643.1"},
  {id:"impulsivity-5",category:"impulsivity-mood-wm",sampleSize:"60",controlGroup:"Active (non-adaptive dual 1-back task)",description:"High-worriers were randomized to one of four training conditions for 7 days: adaptive working memory training (dual n-back), mindfulness meditation practice (MMP), a combination of both, or an active control task (non-adaptive 1-back). While all groups showed reduced worry over time, the combined training group (working memory + mindfulness) demonstrated the greatest and most sustained reductions in worry at the one-week follow-up. Additionally, greater engagement with the working memory training (measured by performance improvement) was correlated with larger gains in attentional control and resilience.",link:"https://doi.org/10.1016/j.brat.2016.11.002",doi:"10.1016/j.brat.2016.11.002"},
  {id:"impulsivity-6",category:"impulsivity-mood-wm",sampleSize:"19",controlGroup:"Active (social skills training)",description:"Unmedicated children with ADHD combined subtype underwent 10 days of paper-and-pencil cognitive training guided by a therapist, or an active social skills control intervention. The cognitive training involved exercises such as labyrinths (planning), word list recall (memory), code deciphering (problem-solving), and detecting missing numbers (attention), which were presented in a mixed order rather than by category. This intervention led to increased neural activity in the right inferior frontal cortex and cerebellumâ€”regions typically hypoactive in ADHDâ€”mimicking the neural effects of psychostimulant medication.",link:"https://doi.org/10.1002/hbm.20988",doi:"10.1002/hbm.20988"},
  {id:"impulsivity-7",category:"impulsivity-mood-wm",sampleSize:"66 (41 patients, 25 healthy controls)",controlGroup:"Active (Treatment as Usual)",description:"Male inpatients being treated for methamphetamine use disorder were assigned to 4 weeks of daily computerized working memory training (N-back) alongside standard psychological care, or standard care alone. The training group demonstrated widespread increases in gray matter volume in the bilateral basal ganglia (specifically the putamen, extending to the amygdala and hippocampus) and reductions in cerebellar volume. These structural brain changes coincided with significantly greater improvements in self-reported impulsivity and self-regulation compared to the group receiving standard care only.",link:"https://doi.org/10.1016/j.nicl.2016.08.019",doi:"10.1016/j.nicl.2016.08.019"},
  {id:"impulsivity-8",category:"impulsivity-mood-wm",sampleSize:"120 (analyzed)",controlGroup:"Active (non-adaptive dual 1-back)",description:"Adolescents (mean age ~13) were assigned to up to 20 days of adaptive dual n-back working memory training or a non-adaptive active control task. The adaptive training group demonstrated significant reductions in self-reported anxiety and depression symptoms compared to the control group. Importantly, these beneficial effects on emotional vulnerability were sustained at a 1-month follow-up, suggesting that working memory training can effectively reduce risk for internalizing disorders in non-clinical youth.",link:"https://doi.org/10.1111/desc.12831",doi:"10.1111/desc.12831"},
  {id:"impulsivity-9",category:"impulsivity-mood-wm",sampleSize:"46",controlGroup:"Active (verbal ability training)",description:"Young adults (ages 18â€“29) with mild to moderate depressive symptoms were randomized to 8 weeks of mobile-based computerized cognitive training targeting either executive functions and processing speed (EF/PS) or verbal abilities (active control). Both groups demonstrated significant improvements in depressed mood, everyday functioning, and cognition, with no significant difference in the magnitude of symptom reduction between conditions. However, the EF/PS group achieved these comparable clinical benefits in approximately half the training time of the verbal group and demonstrated significantly greater gains in specific measures of processing speed and cognitive flexibility.",link:"https://doi.org/10.1016/j.jad.2018.10.109",doi:"10.1016/j.jad.2018.10.109"},
  {id:"impulsivity-10",category:"impulsivity-mood-wm",sampleSize:"146 (70 in Boston, 76 in Sweden)",controlGroup:"Active (non-adaptive low-load training)",description:"Healthy older adults were randomized to 5 weeks of computerized physical exercise, adaptive working memory training (Cogmed), mindfulness practice, or an active control condition. Only the <strong>adaptive cognitive training</strong> group demonstrated a significant increase in serum levels of Brain-Derived Neurotrophic Factor (BDNF)â€”a protein crucial for neuroplasticityâ€”compared to the control group. Neither physical exercise nor mindfulness practice led to significant changes in resting BDNF levels over the 5-week period.",link:"https://doi.org/10.3233/JAD-190756",doi:"10.3233/JAD-190756"},
  {id:"impulsivity-11",category:"impulsivity-mood-wm",sampleSize:"75",controlGroup:"Active (non-adaptive low-load training)",description:"Older adults (ages 65â€“86) were randomized to 5 weeks of adaptive computerized cognitive training (CCT) or a non-adaptive active control task. The adaptive training group demonstrated significant increases in serum BDNF levels and improved performance on the Digit Symbol Test (measuring processing speed and working memory). Mediation analysis revealed that the training-induced augmentation of BDNF significantly accounted for the observed improvements in cognitive performance.",link:"https://doi.org/10.1002/alz.054027",doi:"10.1002/alz.054027"},
  {id:"fat-1",category:"far-analogy-training",sampleSize:"144 (72 in Experiment 1; 72 in Experiment 2)",controlGroup:"Active (generating solutions to near analogies)",description:"'Two experiments investigated whether solving 'distant analogies' (finding connections between conceptually far-removed items) influences how individuals process visual information. Participants who solved distant analogies subsequently showed a stronger 'global bias'â€”the tendency to prioritize the overall structure of a shape rather than its local detailsâ€”on both the Kimchi-Palmer task and the Navon letter task. This suggests that the abstract, broad thinking required for distant analogies 'primes' a global processing style in the visual domain.'",link:"https://doi.org/10.1007/s00426-023-01897-7",doi:"10.1007/s00426-023-01897-7"},
  {id:"fat-2",category:"far-analogy-training",sampleSize:"60",controlGroup:"Active (generating solutions to near analogies)",description:"'Participants were assigned to solve either 'far analogies' (conceptually distant) or 'near analogies' (conceptually similar) before completing a triad classification task. Those in the far analogy group showed a significant preference for categorizing information based on <strong>thematic relations</strong> (e.g., pairing a bee with a flower) rather than taxonomic relations (e.g., pairing a bee with a butterfly). This suggests that thinking through distant analogies shifts cognitive processing toward identifying functional or situational connections between objects.'",link:"https://doi.org/10.1007/s10339-023-01148-y",doi:"10.1007/s10339-023-01148-y"},
  {id:"fat-3",category:"far-analogy-training",sampleSize:"241 (112 in Study 1; 129 in Study 2)",controlGroup:"N/A (Individual differences study)",description:"This research examined how an individual's 'global precedence'â€”the tendency to perceive the 'big picture' before local detailsâ€”relates to how they organize semantic knowledge. Across two studies using the Navon task (to measure visual global-local bias) and triad classification tasks, the researchers found that individuals with a stronger global precedence were significantly faster at recognizing <strong>thematic relations</strong> (e.g., bee and flower) and more likely to choose them over taxonomic relations (e.g., bee and butterfly). The findings suggest that a person's basic perceptual style in the visual domain predicts their conceptual preference for holistic, situational connections in the semantic domain.",link:"https://doi.org/10.3758/s13423-025-02655-z",doi:"10.3758/s13423-025-02655-z"},
  {id:"eft-1",category:"executive-function-training",sampleSize:"143 (fully-trained: 45; partially-trained: 42; control: 56)",controlGroup:"Passive (no involvement)",description:"'Healthy young adults (ages 19â€“45) were assigned to six days of adaptive <strong>Executive Working Memory (EWM)</strong> training using a letter-number sequencing task (full or partial versions) or a passive control group. The fully-trained group demonstrated significant 'far transfer' effects to <strong>cognitive flexibility</strong>, making fewer total errors and completing more stages on the Intra-Extra Dimensional Shift (ID/ED) task compared to the control group. Notably, participants with poorer baseline cognitive flexibility showed the greatest improvements, suggesting a compensatory effect where those with lower initial capacity have more 'space' for training-induced gains.'",link:"https://doi.org/10.1007/s12144-022-03363-w",doi:"10.1007/s12144-022-03363-w"},
  {id:"ef-1",category:"executive-function",sampleSize:"134 (total across three experiments: 45 in Exp 1, 49 in Exp 2, 89 in Exp 3)",controlGroup:"Active (Bookworm word search game) and Passive (Inactive control)",description:"'College students played a custom-designed video game, <strong>Alien Game</strong>, designed to train the executive function skill of <strong>shifting (task switching)</strong>. In the game, players shoot food or drink to aliens based on rules (e.g., color or number of eyes) that constantly change, forcing them to shift their response criteria. Participants who played for <strong>2 hours</strong> showed significantly improved performance on non-game cognitive shifting tests (DCCS and Letter-Number tasks) compared to controls, with particularly large gains for those who reached high levels of challenge in the game. No significant improvements were found for those who played for only 1 hour, suggesting that a sufficient 'dosage' of training is required for skills to transfer.'",link:"https://doi.org/10.1016/j.cedpsych.2017.07.002",doi:"10.1016/j.cedpsych.2017.07.002"},
  {id:"ef-2",category:"executive-function",sampleSize:"82",controlGroup:"N/A (single-group pre-post design)",description:"Adolescent high school students (average age 15.5) played a custom-designed digital game, <strong>Alien Game</strong>, for 20 minutes per week over six weeks. The game targets the executive function subskill of <strong>shifting</strong> by requiring players to provide food or drink to aliens based on rules that reverse or become more complex as levels increase. After the intervention, students showed significant improvements in shifting (DCCS task) and inhibition (Flanker task), with shifting gains directly predicted by their performance within the game. These results suggest that custom-built games explicitly designed to train specific cognitive skills can be effective developmental tools for adolescents.",link:"https://doi.org/10.1016/j.compedu.2017.09.011",doi:"10.1016/j.compedu.2017.09.011"},
  {id:"ea-1",category:"executive-attention",sampleSize:"173 (37 High Executive Attention, 36 Low Executive Attention, 100 Blank Control)",controlGroup:"Active (Low executive attention task) and Blank control",description:"In a study investigating the link between executive attention and fluid intelligence, healthy young adults were assigned to an anti-saccade training intervention with varying ratios of difficulty, or a control condition. Participants in the high executive attention (HEA) group, who performed tasks requiring active inhibitory control, reacted significantly faster in subsequent analogical reasoning tasks compared to the active and blank control groups. EEG analysis revealed that these behavioral improvements were associated with enhanced resting alpha power and larger late positive components (LPC), suggesting that executive attention training improves reasoning by facilitating relation integration rather than enhancing lower-level perceptual processing.",link:"https://doi.org/10.1007/s12264-022-00941-7",doi:"10.1007/s12264-022-00941-7"},
  {id:"mot-1",category:"multiple-object-tracking",sampleSize:"Review Article (Synthesizes multiple studies involving healthy adults, athletes, aging populations, and clinical groups)",controlGroup:"Variable (Evaluates results from various randomized controlled trials and pilot studies)",description:"This review examines the empirical foundations and effectiveness of 3D-Multiple Object Tracking (3D-MOT) as a behavioral intervention for cognitive enhancement. The paradigm challenges core mental skillsâ€”including distributed attention, working memory, and executive functionsâ€”by requiring users to track moving targets within a stereoscopic 3D environment. Synthesized research indicates that 3D-MOT training produces significant transfer effects, such as improved information processing speed in healthy adults, enhanced biological motion perception in the elderly, and superior on-field decision-making in elite athletes. The tool's efficacy is attributed to its high ecological validity and an adaptive staircase protocol that keeps participants within their 'zone of proximal development' to maximize learning gains.",link:"https://doi.org/10.1684/nrp.2022.0710",doi:"10.1684/nrp.2022.0710"},
  {id:"mot-2",category:"multiple-object-tracking",sampleSize:"70 adult participants (35 male, ages 19â€“30)",controlGroup:"None (correlational study comparing intellectual styles and IQ levels)",description:"Young adults completed a 3D Multiple Object-Tracking (3D-MOT) task and the Wechsler Abbreviated Scale of Intelligence-2nd edition (WASI-II) to investigate the relationship between attentional resource capacity and fluid reasoning intelligence. Participants tracked one, two, three, and four target objects out of eight, with task speed automatically adapting based on their performance. As the number of target objects increased, tracking speed decreased following a logarithmic trend, serving as a proxy for individual attentional resource capacity. The results revealed that performance at high cognitive load (tracking four targets) was the strongest predictor of fluid reasoning intelligence, whereas no significant relationship was found with verbal intelligence. Furthermore, individuals characterized by a 'fluid reasoning' intellectual style or higher fluid reasoning IQ significantly outperformed those with a 'verbal' style or lower IQ scores. These findings suggest that 3D-MOT is a sensitive, non-verbal tool for characterizing the underlying commonalities between controlled attention and fluid intelligence.",link:"https://doi.org/10.1016/j.intell.2018.06.001",doi:"10.1016/j.intell.2018.06.001"},
  {id:"mot-3",category:"multiple-object-tracking",sampleSize:"60 (male lower secondary school students; 30 experimental, 30 control)",controlGroup:"No-training (followed normal daily routines)",description:"Male lower secondary school students participated in a study to determine if visual perception training using 3D Multiple Object Tracking (3D-MOT) could enhance cognitive abilities. The experimental group completed 20 sessions of NeuroTracker trainingâ€”conducted as three 10-minute sessions per day over seven daysâ€”using a 65-inch 3D display. Performance was evaluated through standardized tests measuring spatial ability and semantic memory. The results demonstrated that the 3D-MOT training group achieved significantly higher cognitive ability scores than the control group (p < .01). Specifically, the training group showed robust improvements in spatial ability (Cohen's d = 1.79) and semantic memory (Cohen's d = 1.49). These findings suggest that 3D-MOT training effectively stimulates neural networks associated with attention and memory, leading to measurable gains in higher-order cognitive functions even within a short-term intervention.",link:"https://so03.tci-thaijo.org/index.php/RMCS/article/view/100435",doi:""},
  {id:"mot-4",category:"multiple-object-tracking",sampleSize:"20 (10 experimental, 10 active control)",controlGroup:"Active (visual discrimination and the puzzle game 2048)",description:"Young adults (ages 23â€“33) completed ten 30-minute sessions of 3D-Multiple Object Tracking (3D-MOT) training over five weeks to evaluate cognitive transfer to the Useful Field of View (UFOV), a standard measure of driving-related attention. The 3D-MOT group exhibited significant improvements in UFOV performance compared to an active control group, which showed only minor, non-significant gains. These findings suggest that 3D-MOT and UFOV share underlying cognitive mechanisms, specifically selective and divided attention. The results indicate that these critical driving-related abilities can be effectively trained and measured in young adults. Ultimately, the study supports the potential of 3D-MOT as a non-invasive tool for enhancing cognitive functions essential for driver safety.",link:"https://doi.org/10.1097/WNR.0000000000001807",doi:"10.1097/WNR.0000000000001807"},
];

